This is a common feature in other coding agents. For example:

**opencode:**
```
{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "gemini": {
      "npm": "@ai-sdk/google",     <--- IMPORTANT PART!!!
      "name": "Google: Gemini 2.5 pro (custom)",
      "options": {
        "baseURL": "https://my_proxy_domain/v1beta/",
        "apiKey": "my_api_key"
      },
      "models": {
        "gemini-2.5-pro": {
          "name": "Gemini 2.5 pro"
        }
      }
    }
