```

**claude-code-router:**
```
{
  "Providers": [
    {
      "name": "gemini",
      "api_base_url": "https://my_proxy_domain/v1beta/models/",
      "api_key": "my_api_key",
      "models": ["gemini-2.5-flash", "gemini-2.5-pro"],
      "transformer": {
